"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center whitespace-nowrap text-sm font-black uppercase tracking-wider transition-all focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 ring-offset-background",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground border-[var(--border-comic)] border-border rounded-[var(--radius-comic)] shadow-[var(--shadow-comic)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-[var(--shadow-comic-hover)] active:translate-x-[4px] active:translate-y-[4px] active:shadow-[var(--shadow-comic-active)]",
        destructive:
          "bg-destructive text-destructive-foreground border-[var(--border-comic)] border-border rounded-[var(--radius-comic)] shadow-[var(--shadow-comic)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-[var(--shadow-comic-hover)] active:translate-x-[4px] active:translate-y-[4px] active:shadow-[var(--shadow-comic-active)]",
        outline:
          "border-[var(--border-comic)] border-border bg-background hover:bg-secondary hover:text-secondary-foreground rounded-[var(--radius-comic)] shadow-[var(--shadow-comic)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-[var(--shadow-comic-hover)] active:translate-x-[4px] active:translate-y-[4px] active:shadow-[var(--shadow-comic-active)]",
        secondary:
          "bg-secondary text-secondary-foreground border-[var(--border-comic)] border-border rounded-[var(--radius-comic)] shadow-[var(--shadow-comic)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-[var(--shadow-comic-hover)] active:translate-x-[4px] active:translate-y-[4px] active:shadow-[var(--shadow-comic-active)]",
        ghost: "hover:bg-accent hover:text-accent-foreground rounded-[var(--radius-comic)]",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 rounded-md px-3",
        lg: "h-11 rounded-md px-8 text-base",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button"
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }

"use client"

import * as React from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"

import { cn } from "@/lib/utils"

export type CalendarProps = React.HTMLAttributes<HTMLDivElement> & {
  selected?: Date
  onSelect?: (date: Date) => void
  month?: Date
  onMonthChange?: (month: Date) => void
}

const Calendar = React.forwardRef<HTMLDivElement, CalendarProps>(
  ({ className, selected, onSelect, month: monthProp, onMonthChange, ...props }, ref) => {
    const [currentMonth, setCurrentMonth] = React.useState(monthProp || new Date())

    // Update internal state if controlled prop changes
    React.useEffect(() => {
      if (monthProp) setCurrentMonth(monthProp)
    }, [monthProp])

    const handleMonthChange = (newMonth: Date) => {
      setCurrentMonth(newMonth)
      onMonthChange?.(newMonth)
    }

    const nextMonth = () => {
      handleMonthChange(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1))
    }

    const prevMonth = () => {
      handleMonthChange(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1))
    }

    const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate()
    const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay()

    const days = []
    for (let i = 0; i < firstDayOfMonth; i++) {
      days.push(null)
    }
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(new Date(currentMonth.getFullYear(), currentMonth.getMonth(), i))
    }

    const isSameDay = (d1?: Date | null, d2?: Date | null) => {
      if (!d1 || !d2) return false
      return d1.getDate() === d2.getDate() && 
             d1.getMonth() === d2.getMonth() && 
             d1.getFullYear() === d2.getFullYear()
    }

    const monthYearString = currentMonth.toLocaleDateString("en-US", { month: "long", year: "numeric" })
    const dayNames = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"]

    return (
      <div 
        ref={ref} 
        className={cn(
          "p-4 bg-white dark:bg-card border-[3px] border-black dark:border-border rounded-[var(--radius-comic)] shadow-[var(--shadow-comic)] inline-block select-none", 
          className
        )} 
        {...props}
      >
        <div className="flex justify-between items-center mb-4">
          <button 
            type="button"
            onClick={prevMonth}
            className="h-8 w-8 inline-flex justify-center items-center rounded-full bg-white dark:bg-card border-[2px] border-black dark:border-border shadow-[var(--shadow-comic-sm)] hover:-translate-y-[2px] transition-transform active:translate-y-0 active:shadow-none"
          >
            <ChevronLeft className="h-4 w-4 stroke-[3px]" />
          </button>
          <div className="font-black uppercase tracking-wider text-sm">
            {monthYearString}
          </div>
          <button 
            type="button"
            onClick={nextMonth}
            className="h-8 w-8 inline-flex justify-center items-center rounded-full bg-white dark:bg-card border-[2px] border-black dark:border-border shadow-[var(--shadow-comic-sm)] hover:-translate-y-[2px] transition-transform active:translate-y-0 active:shadow-none"
          >
            <ChevronRight className="h-4 w-4 stroke-[3px]" />
          </button>
        </div>

        <div className="grid grid-cols-7 gap-1 text-center mb-2">
          {dayNames.map(day => (
            <div key={day} className="text-[10px] font-black uppercase text-muted-foreground">
              {day}
            </div>
          ))}
        </div>

        <div className="grid grid-cols-7 gap-1">
          {days.map((date, i) => {
            if (!date) return <div key={`empty-${i}`} className="h-8 w-8" />

            const isSelected = isSameDay(date, selected)
            const isToday = isSameDay(date, new Date())

            return (
              <button
                key={date.toISOString()}
                type="button"
                onClick={() => onSelect?.(date)}
                className={cn(
                  "h-8 w-8 inline-flex justify-center items-center rounded-full text-sm font-bold border-[2px] transition-all",
                  isSelected 
                    ? "bg-primary text-primary-foreground border-black shadow-[var(--shadow-comic-sm)] scale-110 font-black z-10" 
                    : "bg-transparent border-transparent hover:border-black dark:hover:border-border hover:bg-secondary",
                  isToday && !isSelected && "text-blue-600 dark:text-blue-400 font-black underline underline-offset-2"
                )}
              >
                {date.getDate()}
              </button>
            )
          })}
        </div>
      </div>
    )
  }
)
Calendar.displayName = "Calendar"

export { Calendar }

